head.script:
// 세션정보를 얻기위한 함수사용
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.init();
        await scwin.listSync1();
        await scwin.listSync2();
        await scwin.listSync3();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF24601.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

// 오늘날짜

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    edt_Date.setValue(scwin.vCurDate);
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listSync1();
        await scwin.listSync2();
        await scwin.listSync3();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF24601.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_List1_OnLoadError
 * @description dts_List1 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List1_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF24601.dts_List1_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_Date_onclick
 * @description btn_Date 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Date_onclick = function() {
    try {
        popUpCalendar2(edt_Date);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF24601.btn_Date_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF24601.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel1_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel1_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF24601.xml", SCREN_PROCS_TP_CD_01);
        $c.data.downloadGridViewExcel(grd_List1, {fileName: "ETF,ETN 상품유형", type: "3"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF24601.btn_Excel1_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel2_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel2_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF24601.xml", SCREN_PROCS_TP_CD_01);
        $c.data.downloadGridViewExcel(grd_List2, {fileName: "ETF,ETN 상품유형", type: "3"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF24601.btn_Excel2_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel3_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel3_onclick = function() {
