        $c.exception.handleError(ex, { context : "ULDSTF24601.btn_Excel3_onclick" });
    }
};

/**
 * @method
 * @name dts_List1_OnLoadCompleted
 * @description dts_List1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List1_OnLoadCompleted = function(rowcount) {
};

/**
 * @method
 * @name dts_List2_OnLoadCompleted
 * @description dts_List2 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List2_OnLoadCompleted = function(rowcount) {
