///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync1
 * @description 지수산출기관 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync1 = async function() {
    url += "&method=listGeneral&outputMessageId=ETF_ETN_PROD_TP_CD_INOUT";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=lds.stf.lstsrch.idx.calc.inst.select.list.condition" + "&{P}param01=" + edt_Date.getValue(); // 조회일자

    const sbmOptions = {
        id : "sbm_dts_List1",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

