    url += "&queryId=lds.stf.lstsrch.idx.mkt.clss.select.list.condition" + "&{P}param01=" + edt_Date.getValue() + // 조회일자
        "&{P}param02=" + edt_Date.getValue() + // 조회일자
        "&{P}param03=" + edt_Date.getValue() + // 조회일자
        "&{P}param04=" + edt_Date.getValue(); // 조회일자
    const sbmOptions = {
        id : "sbm_dts_List2",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List2=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

